// Re-exports every ts-rs generated type from ui/src/lib/bindings/index.ts so the UI can
// `import type { Host } from '$lib/bindings'`. Run after `cargo test` regenerates bindings.
import { readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = join(dirname(fileURLToPath(import.meta.url)), '..', 'ui', 'src', 'lib', 'bindings');
const names = readdirSync(dir)
  .filter((f) => f.endsWith('.ts') && f !== 'index.ts')
  .map((f) => f.slice(0, -3))
  .sort();

const body =
  '// Generated by scripts/gen-bindings-index.mjs — do not edit.\n' +
  names.map((n) => `export type { ${n} } from './${n}';`).join('\n') +
  '\n';
writeFileSync(join(dir, 'index.ts'), body);
console.log(`bindings/index.ts: ${names.length} types`);
